function update(dt) {
    // player movement
    player.dx = 0;
    if (keys.left) player.dx = -player.speed;
    if (keys.right) player.dx = player.speed;
    player.x += player.dx;
    // keep within canvas
    if (player.x < 0) player.x = 0;
    if (player.x + player.w > WIDTH) player.x = WIDTH - player.w;

    // blocks spawning and movement
    blockTimer += dt;
    if (blockTimer > blockInterval) {
      spawnBlock();
      blockTimer = 0;
      if (blockInterval > 400) blockInterval -= 20;
      speedY += 0.02;
    }
    for (let i = blocks.length - 1; i >= 0; i--) {
      const b = blocks[i];
      b.y += speedY;
      // collision with player
      if (b.y + b.h > player.y && b.y < player.y + player.h && b.x < player.x + player.w && b.x + b.w > player.x) {
        gameOver = true;
      }
      // passed bottom – create burst and score
      if (b.y > HEIGHT) {
        for (let j = 0; j < 6; j++) {
          particles.push({
            x: b.x + b.w / 2,
            y: HEIGHT,
            r: Math.random() * 2 + 1,
            vx: (Math.random() - 0.5) * 2,
            vy: -Math.random() * 2 - 0.5,
            alpha: 1,
            color: '#ff6b6b'
          });
        }
        blocks.splice(i, 1);
        score++;
      }
    }

    // update particles
    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.vy += 0.05; // gravity
      p.alpha -= 0.02;
      if (p.alpha <= 0) particles.splice(i, 1);
    }
  }

